{
  "probability": 0.94,
  "range_low": 0.88,
  "range_high": 0.98,
  "summary": [
    "February 2026 showed about 606 Mediterranean deaths/missing, so reaching 900 by end-March requires a strong March surge.",
    "Historical baselines (~1,000–1,300 annual toll) plus 2025 patterns suggest a high-year context; a 900-by-March scenario is plausible but not guaranteed.",
    "There is no formal 2026 forecast; ongoing high early-year signals and data revisions drive the posterior upward, though uncertainty remains.",
    "March-specific weather or SAR/policy dynamics could push the total either higher or lower, depending on incidents and responses."
  ],
  "confidence": "high",
  "narrative": "Anchor around a 60% starting probability with a high early-year toll. February data imply a substantial March spike would be needed to reach 900, and signals of a potential record year support a high posterior, but lack of a formal forecast and possible revisions introduce uncertainty. The calibrated estimate assigns a 0.94 posterior probability with a wide, but plausible, range."
  ,
  "justification": {
    "anchor": {
      "probability": 0.60,
      "basis": "Forecast anchor from IOM Missing Migrants Project on central Mediterranean fatalities; historically ~1,000–1,300 deaths per year, with 2025 around 1,328 across routes (central ~895). This provides the starting point for 2026."
    },
    "factor_updates": [
      {
        "factor": "Current pace through February 2026 (≈606 deaths/missing by end of February)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "With ~606 through February, March would need at least 294 more to reach 900; a sustained March surge is plausible given ongoing risk signals."
      },
      {
        "factor": "Early-year toll signals a potential record year",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Media/IOM signals of a high early-year toll raise the probability of a high annual toll, increasing odds of hitting 900 by March."
      },
      {
        "factor": "Lack of formal 2026 forecast / reliance on real-time counts",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "No official 2026 forecast; predictions depend on evolving data, introducing uncertainty about short-run outcomes."
      },
      {
        "factor": "March-specific weather/incident risk",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Adverse sea conditions or mass incidents could push March fatalities higher, increasing the likelihood of reaching 900."
      },
      {
        "factor": "SAR capacity and policy responses",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Improved SAR or restrictive policies could reduce crossings and fatalities, tempering the probability of hitting 900."
      },
      {
        "factor": "Data reporting delays and potential revisions to early-year counts",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Late updates or revisions could push observed totals higher, nudging March totals upward even if underlying risk remains."
      }
    ],
    "synthesis_rationale": "The factors collectively tilt toward a higher probability of reaching 900 by end-March given the currently elevated pace and signals of a record year, tempered by data gaps and potential policy responses. The posterior probability of 0.94 reflects substantial but not absolute certainty, acknowledging potential correlations among pace, record-year signals, and reported counts."
  }
}

